Lemma zeros24_cells : forall m E, rw_cells asegs m E [CB 24 (poison_bytes 24 0)] -> rw_cells asegs m E (ErrCodeCells EC_clear).
Proof.
  intros m E V. unfold ErrCodeCells, EC_clear. cbn [ec_val ec_cat ec_flags].
  eapply rw_cells_reshape; [exact V| cbn; repeat split; reflexivity| vm_compute; reflexivity].
Qed.

Local Ltac ecclear_script :=
  intros ra sp gp tp t0 t1 t2 s0 s1 a0 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m E lo ej;
  intros EC ST LO CEIL APE MI AC AE SV;
  pose proof (bv_unsigned_in_range 64 sp) as SPR; unfold bv_modulus in SPR; change (2 ^ Z.of_N 64) with (2^64) in SPR;
  pose proof (aapp_bounds _ 24 APE ltac:(lia)) as (EB1 & EB2 & EB3 & EB4 & EB5);
  pose proof aceil_facts as (AF1 & AF2 & AF3);
  pose proof (munch_refl [(lo, bv_unsigned sp); (E, E + 24)]%Z m) as MU; pose proof (wmono_refl asegs m) as WM;
  assert (FW : Forall awin [(lo, bv_unsigned sp); (E, E + 24)]%Z)
    by (apply Forall_cons; [apply awin_stack; exact CEIL| apply Forall_cons; [eapply awin_aapp; [exact APE| clear; lia| clear; lia]| apply Forall_nil]]);
  unfold ECCLEAR_STACK, AINTRIN_STACK, AAPP_HI, AIMG_TOP in *; unfold wz in *;
  carve_frame 16%nat ST;
  unfold P_A_ON_HEADER_IMPL, P_A_ON_FINISH_IMPL;
  (* [comment removed for export] *)
  step; st1; step; step; step; step;
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mc _) =>
    let AE1 := fresh "AE1" in let AC1 := fresh "AC1" in let SV1 := fresh "SV1" in
    pose proof (acc_transport_awin _ _ mc E 24 AE MU FW) as AE1;
    pose proof (aconst_transport_awin _ _ mc AC MU WM FW) as AC1;
    assert (SV1 : shvis mc E (E + 24))
      by (apply (aobj_sub_shvis mc E 24 E 24 (aobj_transport _ _ mc E 24 (aobj_aapp m E 24 APE ltac:(clear; lia) AE SV) MU WM FW));
          clear; lia);
    callZc (asan_memset_specZ MEMSET _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ _ (bv_unsigned sp + -16) E 0 24 ej lo)
           (clear EC ST);
    [ clear; lia | exact EC | clear; lia | clear - EB4; lia
    | exact AE1 | exact SV1
    | eapply aapp_in_app_mem; [exact APE| clear; lia| clear; lia]
    | eapply aconst_ok_aapp; [exact APE| clear; lia| clear; lia]
    | exact ST | exact CEIL | clear - LO; lia | clear - SPR; lia
    | left; clear - EB2 CEIL; lia | assumption | exact AC1 | ];
    clear AE1 SV1 AC1
  end;
  (* [comment removed for export] *)
  step; step;
  lazymatch goal with FR : rw_cells _ _ (bv_unsigned sp + -16) _, ST' : stk _ _ lo _ |- _ => release_frame FR ST' (bv_unsigned sp) end;
  step;
  lazymatch goal with V : rw_cells _ _ E [CB _ (poison_bytes _ 0)] |- _ =>
    let EC' := fresh "EC'" in pose proof (zeros24_cells _ _ V) as EC'; clear V end;
  finish.
