(* [comment removed for export] *)
Definition st_side (m : mem) (P E lo shi : Z) : Prop := pside2 m lo shi [(P, 80); (E, 24)] [(E, 24)].

Lemma st_side_intro : forall m P E lo shi,
  ACONST m -> stack0 m lo shi -> AXStatics2 m -> accessible m P 80 -> accessible m E 24 -> shvis m E (E + 24) ->
  aapp E 24 -> st_side m P E lo shi.
Proof.
  intros m P E lo shi AC SK XS AP AE SV APE. apply pside2_intro; [exact AC| exact SK| exact XS| |].
  - apply Forall_cons; [exact AP| apply Forall_cons; [exact AE| apply Forall_nil]].
  - apply Forall_cons; [| apply Forall_nil]. cbn [fst snd]. apply shv_entry; [exact APE| lia| exact SV].
Qed.

(* [comment removed for export] *)
Lemma body_pwin : forall B sp P E lo shi, st_pure B sp P E lo shi -> Forall pwin (body_W lo sp P E).
Proof.
  intros B sp P E lo shi (LO & CEIL & APP & PAL & APE & EAL & DPE & SPAL & SHI).
  unfold body_W. repeat apply Forall_cons; [| | | | apply Forall_nil].
  - apply pwin_stack. exact CEIL.
  - eapply pwin_aapp; [exact APP| clear; lia| clear; lia].
  - eapply pwin_aapp; [exact APE| clear; lia| clear; lia].
  - exact pwin_httpcat.
Qed.

(* [comment removed for export] *)
Lemma body_cat_now : forall m m1 (sp : word) P E lo g,
  AHttpCat m g -> munch [(lo, bv_unsigned sp); (P, P + 80); (E, E + 24)]%Z m m1 -> wmono asegs m m1 ->
  aceil <= lo -> aapp P 80 -> aapp E 24 -> AHttpCat m1 g.
Proof.
  intros m m1 sp P E lo g HC MU WM CEIL APP APE. pose proof aceil_facts as (AF1 & _).
  pose proof (aapp_bounds _ _ APP ltac:(lia)) as (B1 & _). pose proof (aapp_bounds _ _ APE ltac:(lia)) as (B2 & _).
  eapply AHttpCat_transport; [exact HC| exact MU| exact WM| |];
    cbn [disjoint_from fst snd]; unfold AG_HTTP_CAT, AG_HTTP_CAT_GUARD, AIMG_TOP in *; repeat split; lia.
Qed.

(* [comment removed for export] *)
Definition peof_ctx (m m1 : mem) (sp s0v s1v s2v s3v rav : word) (P E lo shi : Z) (c : pcore) (pad7 pad2 ej j24 : list byte) (g : bool) : Prop :=
  rw_cells asegs m1 (bv_unsigned sp + -64) [CB 24 j24]
  /\ rw_cells asegs m1 (bv_unsigned sp + -40) [C8 s3v; C8 s2v; C8 s1v; C8 s0v; C8 rav]
  /\ rw_cells asegs m1 P (ParserCoreCells c pad7 pad2)
  /\ rw_cells asegs m1 E [CB 24 ej]
  /\ stk asegs m1 lo (bv_unsigned sp + -64)
  /\ munch (body_W lo sp P E) m m1 /\ wmono asegs m m1 /\ mem_inv asegs m1
  /\ munch [(lo, bv_unsigned sp); (P, P + 80); (E, E + 24)]%Z m m1
  /\ AHttpCat m g /\ st_side m P E lo shi.

Definition peof_exit_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (P E lo shi : Z) (c : pcore) (pad7 pad2 : list byte) (loc : Z) (m : mem) : machine_state -> Prop :=
  fun ms' => exists t0 t1 t2 a0 a1 a2 a3 a4 a5 a6 a7 t3 t4 t5 t6 m',
    ms' = MS (mkR ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (ret_pc ra) fc None m' (seg_rom asegs)
    /\ munch (body_W lo sp P E) m m' /\ wmono asegs m m' /\ mem_inv asegs m'
    /\ stk asegs m' lo (bv_unsigned sp)
    /\ rw_cells asegs m' P (ParserCoreCells c pad7 pad2)
    /\ rw_cells asegs m' E (ErrCodeCells (EC_http_loc HE_PARTIAL_MESSAGE loc))
    /\ AHttpCat m' true /\ AXStatics2 m'
    /\ ACONST m' /\ stack0 m' lo shi.

(* [comment removed for export] *)
Definition peof_exit_stmt (pc loc : Z) : Prop :=
  forall rax ra sp gp tp t0 t1 t2 a0x a1 a2 a3 a4 a5 a6 a7 s0v s1v s1x s2v s3v s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6
    (F : bvmap 5 word) fc (m m1 : mem) (P E lo shi : Z) (c : pcore) (pad7 pad2 ej j24 : list byte) (g : bool),
  peof_ctx m m1 sp s0v s1v s2v s3v ra P E lo shi c pad7 pad2 ej j24 g ->
  st_pure PEOF_STACK sp P E lo shi ->
  (pc = 0xccf04 -> s3x = wz 2) ->
  evt asegs (peof_exit_post ra sp gp tp s0v s1v s2v s3v s4 s5 s6 s7 s8 s9 s10 s11 F fc P E lo shi c pad7 pad2 loc m)
    (MS (mkR rax (Z_to_bv 64 (bv_unsigned sp + -64)) gp tp t0 t1 t2 (wz E) s1x a0x a1 a2 a3 a4 a5 a6 a7
              (wz 2147450880) s3x s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6)
        F (Z_to_bv 64 pc) fc None m1 (seg_rom asegs)).

Lemma ec_loc_cells : forall m E e loc, 1 <= e < 2^31 ->
  rw_cells asegs m E [CB 16 (le8 (Z_to_bv 64 e) ++ le8 (Z_to_bv 64 AG_HTTP_CAT)); C8 (Z_to_bv 64 (loc + 1))] ->
  rw_cells asegs m E (ErrCodeCells (EC_http_loc e loc)).
Proof.
  intros m E e loc He V.
  eapply rw_cells_reshape; [exact V| cbn; repeat split; reflexivity
    | unfold ErrCodeCells, EC_http_loc, ec_make_loc, wz; cbn [ec_val ec_cat ec_flags cells_bytes cbytes app];
      replace (e =? 0) with false by (symmetry; apply Z.eqb_neq; lia);
      rewrite ?app_nil_r, <- ?app_assoc; reflexivity].
Qed.

